\begin{definition}
\label{def:1.1}
A sequence $(x_n)_{n=m}^\infty$ of real numbers \emph{converges} to a real number $x$ if for every $\varepsilon>0$ there exists an integer $N\ge m$ such that for all $n\ge N$ one has $|x-x_n|\le \varepsilon$. In this case, write $\lim_{n\to\infty} x_n=x$.
\end{definition}

\begin{definition}
\label{def:1.2}
The \emph{distance function} $d:\mathbb{R}\times\mathbb{R}\to\mathbb{R}$ is defined by
\[
\label{eq:1.u1}
d(x,y):=|x-y|.
\]
\end{definition}

\begin{lemma}
\label{lem:1.1}
Let $m\in\mathbb{N}$, let $(x_n)_{n=m}^\infty$ be a sequence in $\mathbb{R}$, and let $x\in\mathbb{R}$. Then $(x_n)_{n=m}^\infty$ converges to $x$ if and only if
\[
\label{eq:1.u2}
\lim_{n\to\infty} d(x_n,x)=0,
\]
where $d(a,b)=|a-b|$ is the usual metric on $\mathbb{R}$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:1.1}
Assume $x_n\to x$ in $\mathbb{R}$. By definition, for every $\varepsilon>0$ there exists $N\ge m$ such that for all $n\ge N$,
\[
\label{eq:1.u3}
|x_n-x|<\varepsilon.
\]
Since $d(x_n,x)=|x_n-x|$, this is equivalent to: for every $\varepsilon>0$ there exists $N\ge m$ such that for all $n\ge N$, $d(x_n,x)<\varepsilon$. This is exactly the statement that $d(x_n,x)\to 0$, i.e. $\lim_{n\to\infty} d(x_n,x)=0$.

Conversely, assume $\lim_{n\to\infty} d(x_n,x)=0$. Then for every $\varepsilon>0$ there exists $N\ge m$ such that for all $n\ge N$,
\[
\label{eq:1.u4}
d(x_n,x)<\varepsilon.
\]
Using $d(x_n,x)=|x_n-x|$, this becomes $|x_n-x|<\varepsilon$ for all $n\ge N$, which is the definition of $x_n\to x$.
\end{proof}

