\begin{definition}
\label{def:1.3}
[Metric space]
A \emph{metric space} is a pair $(X,d)$ consisting of a set $X$ and a function $d:X\times X\to [0,+\infty)$ such that, for all $x,y,z\in X$:
\begin{enumerate}
\item $d(x,y)=0$ if and only if $x=y$.
\item $d(x,y)=d(y,x)$.
\item $d(x,z)\le d(x,y)+d(y,z)$.
\end{enumerate}
The function $d$ is called a \emph{metric} on $X$.
\end{definition}

\begin{proposition}
\label{prop:1.1}
Let $(X,d)$ be a metric space. The following statements are equivalent.
\begin{enumerate}
\item For all $x\in X$, $d(x,x)=0$.
\item For all $x,y\in X$, if $d(x,y)=0$ then $x=y$.
\item For all $x,y\in X$, $d(x,y)=0$ if and only if $x=y$.
\end{enumerate}
\end{proposition}

\begin{definition}
\label{def:1.4}
The \emph{standard metric} on $\mathbb{R}$ is the function $d:\mathbb{R}\times\mathbb{R}\to[0,\infty)$ defined by
\[
\label{eq:1.u7}
d(x,y):=|x-y|.
\]
\end{definition}

\begin{definition}
\label{def:1.5}
Let $(X,d)$ be a metric space and let $Y\subseteq X$. The \emph{metric on $Y$ induced by $d$} is the restriction $d|_{Y\times Y}:Y\times Y\to[0,\infty)$ defined by $d|_{Y\times Y}(y_1,y_2):=d(y_1,y_2)$ for all $y_1,y_2\in Y$. The pair $(Y,d|_{Y\times Y})$ is called the \emph{subspace} of $(X,d)$ induced by $Y$.
\end{definition}

\begin{definition}
\label{def:1.6}
Let $n\ge 1$. The \emph{Euclidean metric} (or $\ell^2$ metric) on $\mathbb{R}^n$ is the function $d_{\ell^2}:\mathbb{R}^n\times\mathbb{R}^n\to[0,\infty)$ defined by
\[
\label{eq:1.u8}
d_{\ell^2}(x,y):=\left(\sum_{i=1}^n (x_i-y_i)^2\right)^{1/2},\qquad x=(x_1,\dots,x_n),\ y=(y_1,\dots,y_n).
\]
The metric space $(\mathbb{R}^n,d_{\ell^2})$ is called \emph{Euclidean space of dimension $n$}.
\end{definition}

\begin{definition}
\label{def:1.7}
Let $n\ge 1$. The \emph{taxicab metric} (or $\ell^1$ metric) on $\mathbb{R}^n$ is the function $d_{\ell^1}:\mathbb{R}^n\times\mathbb{R}^n\to[0,\infty)$ defined by
\[
\label{eq:1.u9}
d_{\ell^1}(x,y):=\sum_{i=1}^n |x_i-y_i|,\qquad x=(x_1,\dots,x_n),\ y=(y_1,\dots,y_n).
\]
\end{definition}

\begin{proposition}
\label{prop:1.2}
Let $n\ge 1$ and let $x=(x_1,\dots,x_n),y=(y_1,\dots,y_n)\in\mathbb{R}^n$. Define
\[
\label{eq:1.u10}
d_{\ell^1}(x,y)=\sum_{i=1}^n |x_i-y_i|,\qquad d_{\ell^2}(x,y)=\left(\sum_{i=1}^n |x_i-y_i|^2\right)^{1/2}.
\]
Then
\[
\label{eq:1.u11}
d_{\ell^2}(x,y)\le d_{\ell^1}(x,y)\le \sqrt{n}\, d_{\ell^2}(x,y).
\]
\end{proposition}

\begin{definition}
\label{def:1.8}
Let $n\ge 1$. The \emph{sup norm metric} (or $\ell^\infty$ metric) on $\mathbb{R}^n$ is the function $d_{\ell^\infty}:\mathbb{R}^n\times\mathbb{R}^n\to[0,\infty)$ defined by
\[
\label{eq:1.u14}
d_{\ell^\infty}(x,y):=\sup\{ |x_i-y_i| : 1\le i\le n\},\qquad x=(x_1,\dots,x_n),\ y=(y_1,\dots,y_n).
\]
\end{definition}

\begin{proposition}
\label{prop:1.3}
Let $n\ge 1$. For all $x,y\in\mathbb{R}^n$, the metrics $d_{\ell^\infty}$ and $d_{\ell^2}$ satisfy
\[
\label{eq:1.u15}
\frac{1}{\sqrt{n}}\, d_{\ell^2}(x,y)\le d_{\ell^\infty}(x,y)\le d_{\ell^2}(x,y).
\]
Equivalently, for all $v\in\mathbb{R}^n$,
\[
\label{eq:1.u16}
\frac{1}{\sqrt{n}}\,\|v\|_2\le \|v\|_\infty\le \|v\|_2.
\]
\end{proposition}

\begin{definition}
\label{def:1.9}
[Convergence of sequences in metric spaces]
Let $m\in\mathbb{Z}$, let $(X,d)$ be a metric space, and let $(x^{(n)})_{n=m}^\infty$ be a sequence in $X$. A point $x\in X$ is called a \emph{limit} of the sequence with respect to $d$, and the sequence is said to \emph{converge to $x$ with respect to $d$}, if
\[
\label{eq:1.u19}
\lim_{n\to\infty} d\bigl(x^{(n)},x\bigr)=0.
\]
Equivalently, $(x^{(n)})_{n=m}^\infty$ converges to $x$ with respect to $d$ if and only if for every $\varepsilon>0$ there exists an integer $N\ge m$ such that $d\bigl(x^{(n)},x\bigr)\le \varepsilon$ for all integers $n\ge N$.
\end{definition}

\begin{proposition}
\label{prop:1.4}
Let $(X,d)$ be a metric space, let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$, and let $x\in X$. If $(x^{(n)})_{n=m}^{\infty}$ converges to $x$ with respect to $d$, then for every integer $m'\ge m$ the tail sequence $(x^{(n)})_{n=m'}^{\infty}$ also converges to $x$ with respect to $d$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.4}
Assume $(x^{(n)})_{n=m}^{\infty}$ converges to $x$ with respect to $d$. By definition, for every $\varepsilon>0$ there exists an integer $N\ge m$ such that for all $n\ge N$ one has $d(x^{(n)},x)<\varepsilon$.

Fix an integer $m'\ge m$ and $\varepsilon>0$. Choose $N\ge m$ such that $d(x^{(n)},x)<\varepsilon$ for all $n\ge N$, and define $N':=\max\{N,m'\}$. Then $N'\ge m'$, and for every $n\ge N'$ it follows that $n\ge N$, hence $d(x^{(n)},x)<\varepsilon$. This is exactly the definition of convergence of the tail sequence $(x^{(n)})_{n=m'}^{\infty}$ to $x$.
\end{proof}

