\begin{proposition}
\label{prop:1.5}
[Equivalence of $\ell^1$, $\ell^2$, $\ell^\infty$ convergence in $\mathbf{R}^n$]
Let $n\in\mathbf{N}$, let $(x^{(k)})_{k=m}^{\infty}$ be a sequence in $\mathbf{R}^n$ with $x^{(k)}=(x_1^{(k)},\dots,x_n^{(k)})$, and let $x=(x_1,\dots,x_n)\in\mathbf{R}^n$. Define metrics on $\mathbf{R}^n$ by
\[
\label{eq:1.u20}
d_{\ell^1}(u,v)=\sum_{j=1}^n |u_j-v_j|,\qquad d_{\ell^2}(u,v)=\Bigl(\sum_{j=1}^n |u_j-v_j|^2\Bigr)^{1/2},\qquad d_{\ell^\infty}(u,v)=\max_{1\le j\le n}|u_j-v_j|.
\]
Then the following statements are equivalent:
\begin{enumerate}
\item[(a)] $x^{(k)}\to x$ with respect to $d_{\ell^2}$.
\item[(b)] $x^{(k)}\to x$ with respect to $d_{\ell^1}$.
\item[(c)] $x^{(k)}\to x$ with respect to $d_{\ell^\infty}$.
\item[(d)] For every $1\le j\le n$, the real sequence $(x_j^{(k)})_{k=m}^{\infty}$ converges to $x_j$.
\end{enumerate}
\end{proposition}

\begin{proposition}
\label{prop:1.6}
[Convergence in the discrete metric]
Let $X$ be a set and let $d_{\mathrm{disc}}$ be the discrete metric on $X$, i.e., $d_{\mathrm{disc}}(a,b)=0$ if $a=b$ and $d_{\mathrm{disc}}(a,b)=1$ if $a\ne b$. Let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$ (with $m\in\mathbb{N}$) and let $x\in X$. Then $(x^{(n)})_{n=m}^{\infty}$ converges to $x$ with respect to $d_{\mathrm{disc}}$ if and only if there exists an integer $N\ge m$ such that $x^{(n)}=x$ for all $n\ge N$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.6}
Assume that $x^{(n)}\to x$ with respect to $d_{\mathrm{disc}}$. By definition of convergence in a metric space, for $\varepsilon=\tfrac12$ there exists $N\ge m$ such that for all $n\ge N$ one has
\[
\label{eq:1.u26}
d_{\mathrm{disc}}\bigl(x^{(n)},x\bigr)<\tfrac12.
\]
Since $d_{\mathrm{disc}}$ only takes the values $0$ and $1$, the inequality $d_{\mathrm{disc}}(x^{(n)},x)<\tfrac12$ implies $d_{\mathrm{disc}}(x^{(n)},x)=0$, hence $x^{(n)}=x$, for all $n\ge N$.

Conversely, assume there exists $N\ge m$ such that $x^{(n)}=x$ for all $n\ge N$. Let $\varepsilon>0$ be given. For all $n\ge N$,
\[
\label{eq:1.u27}
d_{\mathrm{disc}}\bigl(x^{(n)},x\bigr)=0<\varepsilon.
\]
Therefore, by the definition of convergence, $x^{(n)}\to x$ with respect to $d_{\mathrm{disc}}$.
\end{proof}

