\begin{proposition}
\label{prop:1.7}
[Uniqueness of limits]
Let $(X,d)$ be a metric space, and let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$ for some $m\in\mathbb{N}$. If $(x^{(n)})_{n=m}^{\infty}$ converges to $x\in X$ with respect to $d$ and also converges to $x'\in X$ with respect to $d$, then $x=x'$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.7}
Assume $x^{(n)}\to x$ and $x^{(n)}\to x'$ with respect to $d$. Suppose for contradiction that $x\neq x'$. Then $d(x,x')>0$. Set $\varepsilon:=\tfrac12 d(x,x')>0$.

Since $x^{(n)}\to x$, there exists $N_1\ge m$ such that for all $n\ge N_1$, $d(x^{(n)},x)<\varepsilon$. Since $x^{(n)}\to x'$, there exists $N_2\ge m$ such that for all $n\ge N_2$, $d(x^{(n)},x')<\varepsilon$. Let $N:=\max\{N_1,N_2\}$. Then for all $n\ge N$,
\[
\label{eq:1.u28}
d(x,x')\le d(x,x^{(n)})+d(x^{(n)},x')<\varepsilon+\varepsilon=2\varepsilon=d(x,x'),
\]
which is a contradiction. Hence $x=x'$.
\end{proof}

