\begin{proposition}
\label{prop:1.8}
Let $(X,d)$ be a metric space, and let $f\colon X\to X$ be a bijection. Define $d'\colon X\times X\to[0,\infty)$ by
\[
\label{eq:1.u29}
d'(x,y):=d\bigl(f(x),f(y)\bigr)\qquad (x,y\in X).
\]
Then $d'$ is a metric on $X$.
\end{proposition}

\begin{proposition}
\label{prop:1.9}
Let $X=[0,1]$ and let $d(x,y)=|x-y|$ be the usual metric on $X$. Define a function $f:X\to X$ by
\[
\label{eq:1.u32}
f(0)=1,\qquad f(1)=0,\qquad f(x)=x\text{ for all }x\in(0,1),
\]
and define a metric $d'$ on $X$ by
\[
\label{eq:1.u33}
d'(x,y):=d\bigl(f(x),f(y)\bigr)=\bigl|f(x)-f(y)\bigr|.
\]
Then the sequence $(1/n)_{n\ge 1}$ converges to $1$ with respect to the metric $d'$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.9}
To show $\lim_{n\to\infty} \frac1n = 1$ with respect to $d'$, it suffices to prove: for every $\varepsilon>0$ there exists $N\in\mathbb{N}$ such that $n\ge N$ implies $d'(1/n,1)<\varepsilon$.

Fix $\varepsilon>0$. For $n\ge 2$ one has $1/n\in(0,1)$, hence $f(1/n)=1/n$, while $f(1)=0$. Therefore, for all $n\ge 2$,
\[
\label{eq:1.u34}
d'(1/n,1)=\bigl|f(1/n)-f(1)\bigr|=\left|\frac1n-0\right|=\frac1n.
\]
Choose $N\in\mathbb{N}$ such that $N\ge 2$ and $1/N<\varepsilon$ (for instance, $N=\max\{2,\lceil 1/\varepsilon\rceil\}$). Then for all $n\ge N$,
\[
\label{eq:1.u35}
d'(1/n,1)=\frac1n\le \frac1N<\varepsilon.
\]
This proves $1/n\to 1$ in the metric $d'$.
\end{proof}

