\begin{theorem}
\label{thm:1.1}
[Cauchy--Schwarz inequality]
Let $n\ge 1$ and let $a_1,\dots,a_n,b_1,\dots,b_n\in\mathbb{R}$. Then
\[
\label{eq:1.u36}
\left|\sum_{i=1}^n a_i b_i\right| \le \left(\sum_{i=1}^n a_i^2\right)^{1/2}\left(\sum_{i=1}^n b_i^2\right)^{1/2}.
\]
\end{theorem}

\begin{theorem}
\label{thm:1.2}
[Triangle inequality in $\mathbb{R}^n$ for the Euclidean norm]
Let $n\ge 1$ and let $a_1,\dots,a_n,b_1,\dots,b_n\in\mathbb{R}$. Then
\[
\label{eq:1.u42}
\left(\sum_{i=1}^n (a_i+b_i)^2\right)^{1/2} \le \left(\sum_{i=1}^n a_i^2\right)^{1/2}+\left(\sum_{i=1}^n b_i^2\right)^{1/2}.
\]
\end{theorem}

\begin{proposition}
\label{prop:1.10}
Let $(X,d)$ be a metric space. Let $(x_n)_{n=1}^\infty$ and $(y_n)_{n=1}^\infty$ be sequences in $X$ such that $x_n\to x$ and $y_n\to y$ as $n\to\infty$. Then the real sequence $(d(x_n,y_n))_{n=1}^\infty$ converges and
\[
\label{eq:1.u49}
\lim_{n\to\infty} d(x_n,y_n)=d(x,y).
\]
\end{proposition}

\begin{definition}
\label{def:1.10}
[Balls]
Let $(X,d)$ be a metric space, let $x_0\in X$, and let $r>0$. The (open) ball in $X$ centered at $x_0$ with radius $r$ is the set
\[
\label{eq:1.u55}
B_{(X,d)}(x_0,r):=\{x\in X : d(x,x_0)<r\}.
\]
\end{definition}

\begin{definition}
\label{def:1.11}
Let $(X,d)$ be a metric space and let $E\subseteq X$.
\begin{enumerate}
\item A point $x\in X$ is an \emph{interior point} of $E$ if there exists $r>0$ such that $B_{(X,d)}(x,r)\subseteq E$.
\item A point $x\in X$ is an \emph{exterior point} of $E$ if there exists $r>0$ such that $B_{(X,d)}(x,r)\subseteq X\setminus E$.
\item A point $x\in X$ is a \emph{boundary point} of $E$ if for every $r>0$, both $B_{(X,d)}(x,r)\cap E\neq\varnothing$ and $B_{(X,d)}(x,r)\cap (X\setminus E)\neq\varnothing$.
\end{enumerate}
\end{definition}

\begin{definition}
\label{def:1.12}
[Interior, exterior, boundary]
Let $(X,d)$ be a metric space and let $E\subseteq X$.
\begin{enumerate}
\item A point $x\in X$ is an \emph{interior point} of $E$ if there exists $r>0$ such that $B(x,r)\subseteq E$.
\item A point $x\in X$ is an \emph{exterior point} of $E$ if there exists $r>0$ such that $B(x,r)\cap E=\emptyset$.
\item A point $x\in X$ is a \emph{boundary point} of $E$ if $x$ is neither an interior point nor an exterior point of $E$.
\end{enumerate}
The \emph{interior} of $E$ is the set $\mathrm{int}(E)$ of all interior points of $E$. The \emph{exterior} of $E$ is the set $\mathrm{ext}(E)$ of all exterior points of $E$. The \emph{boundary} of $E$ is the set $\partial E$ of all boundary points of $E$.
\end{definition}

\begin{proposition}
\label{prop:1.11}
Let $(X,d)$ be a metric space and let $E\subseteq X$. Define
\[
\label{eq:1.u56}
\operatorname{int}(E)=\{x\in X: \exists r>0\text{ such that }B(x,r)\subseteq E\},\qquad
\operatorname{ext}(E)=\operatorname{int}(X\setminus E),\qquad
\partial E = X\setminus\bigl(\operatorname{int}(E)\cup \operatorname{ext}(E)\bigr),
\]
where $B(x,r)=\{y\in X: d(x,y)<r\}$. Then:
\begin{enumerate}
\item If $x_0\in \operatorname{int}(E)$, then $x_0\in E$.
\item If $x_0\in \operatorname{ext}(E)$, then $x_0\notin E$.
\item $\operatorname{int}(E)\cap \operatorname{ext}(E)=\varnothing$.
\item If $x_0\in \partial E$, then it is possible that $x_0\in E$ and it is possible that $x_0\notin E$.
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.11}
(1) If $x_0\in \operatorname{int}(E)$, then there exists $r>0$ such that $B(x_0,r)\subseteq E$. Since $x_0\in B(x_0,r)$, it follows that $x_0\in E$.

(2) If $x_0\in \operatorname{ext}(E)=\operatorname{int}(X\setminus E)$, then there exists $r>0$ such that $B(x_0,r)\subseteq X\setminus E$. In particular $x_0\in X\setminus E$, so $x_0\notin E$.

(3) Suppose $x_0\in \operatorname{int}(E)\cap \operatorname{ext}(E)$. Then there exist $r,s>0$ such that $B(x_0,r)\subseteq E$ and $B(x_0,s)\subseteq X\setminus E$. Let $t=\min\{r,s\}>0$. Then $B(x_0,t)\subseteq B(x_0,r)\cap B(x_0,s)\subseteq E\cap (X\setminus E)=\varnothing$, contradicting $x_0\in B(x_0,t)$. Hence the intersection is empty.

(4) Both possibilities occur in metric spaces. For example, in $X=\mathbb{R}$ with the usual metric and $E=[0,1]$, one has $0\in \partial E$ and $0\in E$. For $E=(0,1)$, one has $0\in \partial E$ and $0\notin E$.
\end{proof}

