\begin{proposition}
\label{prop:1.12}
Let $E=[1,2)\subset\mathbb{R}$ endowed with the standard metric $d(x,y)=|x-y|$. Then
\[
\label{eq:1.u57}
\operatorname{int}(E)=(1,2),\qquad \operatorname{ext}(E)=(-\infty,1)\cup(2,\infty),\qquad \partial E=\{1,2\}.
\]
In particular, $1\in E\cap\partial E$ and $2\in \partial E\setminus E$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.12}
For $x\in\mathbb{R}$ and $r>0$, write $B(x,r)=\{y\in\mathbb{R}:|y-x|<r\}$.

\emph{Interior.} If $x\in(1,2)$, set $r=\min\{x-1,2-x\}>0$. Then $B(x,r)\subset(1,2)\subset[1,2)=E$, hence $x\in\operatorname{int}(E)$. Conversely, if $x\in\operatorname{int}(E)$, then $x\in E$, so $x\in[1,2)$. If $x=1$, then for every $r>0$ the point $1-r/2\in B(1,r)$ but $1-r/2<1$, so $1-r/2\notin E$, contradicting $B(1,r)\subset E$; hence $x\neq 1$. Therefore $x\in(1,2)$, proving $\operatorname{int}(E)=(1,2)$.

\emph{Exterior.} If $x<1$, set $r=(1-x)/2>0$. Then $B(x,r)\subset(-\infty,1)\subset\mathbb{R}\setminus E$, so $x\in\operatorname{ext}(E)$. If $x>2$, set $r=(x-2)/2>0$. Then $B(x,r)\subset(2,\infty)\subset\mathbb{R}\setminus E$, so $x\in\operatorname{ext}(E)$. Conversely, if $x\in\operatorname{ext}(E)$, then $x\notin E$, so either $x<1$ or $x\ge 2$. If $x=2$, then for every $r>0$ the point $2-r/2\in B(2,r)$ and satisfies $2-r/2\in(1,2)\subset E$, so $B(2,r)\nsubseteq \mathbb{R}\setminus E$; hence $2\notin\operatorname{ext}(E)$. Therefore $\operatorname{ext}(E)=(-\infty,1)\cup(2,\infty)$.

\emph{Boundary.} By definition, $\partial E=\mathbb{R}\setminus(\operatorname{int}(E)\cup\operatorname{ext}(E))$. Using the computed formulas,
\[
\label{eq:1.u58}
\operatorname{int}(E)\cup\operatorname{ext}(E)=(1,2)\cup\bigl(( -\infty,1)\cup(2,\infty)\bigr)=\mathbb{R}\setminus\{1,2\},
\]
so $\partial E=\{1,2\}$. The final assertions follow since $1\in[1,2)$ but $2\notin[1,2)$.
\end{proof}

