\begin{proposition}
\label{prop:1.13}
Let $X$ be a set equipped with the discrete metric $d_{\mathrm{disc}}$ defined by $d_{\mathrm{disc}}(x,y)=0$ if $x=y$ and $d_{\mathrm{disc}}(x,y)=1$ if $x\neq y$. For every subset $E\subseteq X$, the interior, exterior, and boundary of $E$ satisfy
\[
\label{eq:1.u59}
\operatorname{int}(E)=E,\qquad \operatorname{ext}(E)=X\setminus E,\qquad \partial E=\varnothing.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.13}
Fix $E\subseteq X$. For any $x\in X$, the open ball of radius $\tfrac12$ satisfies $B(x,\tfrac12)=\{x\}$, since $d_{\mathrm{disc}}(x,y)<\tfrac12$ holds if and only if $y=x$.

If $x\in E$, then $B(x,\tfrac12)=\{x\}\subseteq E$, so $x\in\operatorname{int}(E)$. Hence $E\subseteq\operatorname{int}(E)$. The reverse inclusion $\operatorname{int}(E)\subseteq E$ holds by definition of interior, so $\operatorname{int}(E)=E$.

If $x\in X\setminus E$, then $B(x,\tfrac12)=\{x\}\subseteq X\setminus E$, so $x\in\operatorname{int}(X\setminus E)$. By definition, $\operatorname{ext}(E)=\operatorname{int}(X\setminus E)$, hence $\operatorname{ext}(E)=X\setminus E$.

Finally, by definition $\partial E = X\setminus(\operatorname{int}(E)\cup\operatorname{ext}(E))$. Using the previous equalities,
\[
\label{eq:1.u60}
\operatorname{int}(E)\cup\operatorname{ext}(E)=E\cup (X\setminus E)=X,
\]
so $\partial E=X\setminus X=\varnothing$.
\end{proof}

