\begin{definition}
\label{def:1.13}
[Closure]
Let $(X,d)$ be a metric space and let $E\subseteq X$.

A point $x\in X$ is called an \emph{adherent point} of $E$ if for every $r>0$ one has
\[
\label{eq:1.u61}
B(x,r)\cap E\neq\varnothing,
\]
where $B(x,r)=\{y\in X: d(x,y)<r\}$.

The \emph{closure} of $E$, denoted $\overline{E}$, is the set of all adherent points of $E$:
\[
\label{eq:1.u62}
\overline{E}=\{x\in X: \forall r>0,\ B(x,r)\cap E\neq\varnothing\}.
\]
\end{definition}

\begin{proposition}
\label{prop:1.14}
Let $(X,d)$ be a metric space, let $E\subseteq X$, and let $x_0\in X$. The following statements are equivalent:
\begin{enumerate}[(a)]
\item $x_0$ is an adherent point of $E$, i.e., for every $r>0$, $B(x_0,r)\cap E\neq\varnothing$.
\item $x_0$ is either an interior point of $E$ (there exists $r>0$ such that $B(x_0,r)\subseteq E$) or a boundary point of $E$ (for every $r>0$, both $B(x_0,r)\cap E\neq\varnothing$ and $B(x_0,r)\cap (X\setminus E)\neq\varnothing$).
\item There exists a sequence $(x_n)_{n=1}^\infty$ in $E$ such that $x_n\to x_0$ with respect to the metric $d$.
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.14}
(a)$\Rightarrow$(b). Assume $x_0$ is an adherent point of $E$. If $x_0$ is an interior point of $E$, then (b) holds. Otherwise, $x_0$ is not an interior point of $E$, so for every $r>0$ there exists a point in $B(x_0,r)$ that is not in $E$, i.e., $B(x_0,r)\cap (X\setminus E)\neq\varnothing$. Together with adherence, which gives $B(x_0,r)\cap E\neq\varnothing$ for every $r>0$, this shows that $x_0$ is a boundary point of $E$. Hence (b) holds.

(b)$\Rightarrow$(a). If $x_0$ is an interior point of $E$, then there exists $r_0>0$ with $B(x_0,r_0)\subseteq E$, and in particular $B(x_0,r)\cap E\neq\varnothing$ for every $0<r\le r_0$; for $r>r_0$, $B(x_0,r_0)\subseteq B(x_0,r)$ implies $B(x_0,r)\cap E\neq\varnothing$ as well. Thus $x_0$ is adherent. If instead $x_0$ is a boundary point of $E$, then by definition $B(x_0,r)\cap E\neq\varnothing$ for every $r>0$, so again $x_0$ is adherent. Hence (a) holds.

(a)$\Rightarrow$(c). Assume $x_0$ is an adherent point of $E$. For each $n\in\mathbb N$, the open ball $B(x_0,1/n)$ meets $E$, so choose $x_n\in E\cap B(x_0,1/n)$. Then $d(x_n,x_0)<1/n$ for all $n$, hence $d(x_n,x_0)\to 0$, which means $x_n\to x_0$.

(c)$\Rightarrow$(a). Assume there exists a sequence $(x_n)$ in $E$ with $x_n\to x_0$. Let $r>0$. By convergence, there exists $N$ such that for all $n\ge N$, $d(x_n,x_0)<r$, i.e., $x_n\in B(x_0,r)$. In particular, $x_N\in E\cap B(x_0,r)$, so $B(x_0,r)\cap E\neq\varnothing$. Since $r>0$ was arbitrary, $x_0$ is an adherent point of $E$.

Therefore (a), (b), and (c) are equivalent.
\end{proof}

