\begin{theorem}
\label{thm:1.3}
Let $(X,d)$ be a metric space and let $E\subseteq X$. Define
\begin{align*}
\label{eq:1.u63}
\operatorname{int}(E) &:= \{x\in X:\exists r>0\text{ such that }B(x,r)\subseteq E\},\\
\operatorname{ext}(E) &:= \operatorname{int}(X\setminus E),\\
\partial E &:= X\setminus\bigl(\operatorname{int}(E)\cup\operatorname{ext}(E)\bigr),\\
\overline{E} &:= \{x\in X:\forall r>0,\ B(x,r)\cap E\neq\varnothing\}.
\end{align*}
Then
\[
\label{eq:1.u64}
\overline{E}=\operatorname{int}(E)\cup \partial E = X\setminus \operatorname{ext}(E).
\]
\end{theorem}

\begin{definition}
\label{def:1.14}
(Open and closed sets) Let $(X,d)$ be a metric space and let $E\subseteq X$. The set $E$ is called \emph{closed} if $\partial E\subseteq E$. The set $E$ is called \emph{open} if $\partial E\cap E=\emptyset$.
\end{definition}

\begin{proposition}
\label{prop:1.15}
Let $(X,d)$ be a metric space. Then $X$ and $\emptyset$ are both open and closed subsets of $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.15}
A subset $U\subseteq X$ is open if for every $x\in U$ there exists $r>0$ such that $B(x,r)\subseteq U$, where $B(x,r)=\{y\in X: d(x,y)<r\}$.

For $U=X$, given any $x\in X$ and any $r>0$, one has $B(x,r)\subseteq X$, so $X$ is open.

For $U=\emptyset$, the condition defining openness is vacuously true since there is no $x\in\emptyset$; hence $\emptyset$ is open.

A subset $F\subseteq X$ is closed if $X\setminus F$ is open. Since $X\setminus X=\emptyset$ is open, $X$ is closed. Since $X\setminus\emptyset=X$ is open, $\emptyset$ is closed.
\end{proof}

