\begin{proposition}
\label{prop:1.16}
Let $(X,d_{\mathrm{disc}})$ be a set equipped with the discrete metric, i.e. $d_{\mathrm{disc}}(x,y)=0$ if $x=y$ and $d_{\mathrm{disc}}(x,y)=1$ if $x\neq y$. Then every subset $E\subseteq X$ is open and closed in the metric topology induced by $d_{\mathrm{disc}}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.16}
To show that $E$ is open, let $x\in E$ be arbitrary. For $r=\tfrac12$ one has
\[
\label{eq:1.u66}
B_{d_{\mathrm{disc}}}(x,r)=\{y\in X: d_{\mathrm{disc}}(x,y)<\tfrac12\}=\{x\}\subseteq E,
\]
so every $x\in E$ is an interior point of $E$. Hence $E$ is open.

To show that $E$ is closed, it suffices to show that $X\setminus E$ is open. If $x\in X\setminus E$, then again $B_{d_{\mathrm{disc}}}(x,\tfrac12)=\{x\}\subseteq X\setminus E$, so $X\setminus E$ is open. Therefore $E$ is closed.
\end{proof}

