\begin{proposition}
\label{prop:1.17}
[Basic properties of open and closed sets]
Let $(X,d)$ be a metric space.
\begin{enumerate}
\item[(a)] For any $E\subseteq X$, $E$ is open if and only if $E=\operatorname{int}(E)$; equivalently, $E$ is open if and only if for every $x\in E$ there exists $r>0$ such that $B(x,r)\subseteq E$.
\item[(b)] For any $E\subseteq X$, $E$ is closed if and only if $E$ contains all its adherent points; equivalently, $E$ is closed if and only if for every convergent sequence $(x_n)_{n=m}^\infty$ in $E$, the limit $\lim_{n\to\infty} x_n$ also lies in $E$.
\item[(c)] For any $x_0\in X$ and $r>0$, the ball $B(x_0,r)$ is open, and the set $\{x\in X: d(x,x_0)\le r\}$ is closed.
\item[(d)] For any $x_0\in X$, the singleton $\{x_0\}$ is closed.
\item[(e)] For any $E\subseteq X$, $E$ is open if and only if its complement $X\setminus E$ is closed.
\item[(f)] If $E_1,\dots,E_n$ are open subsets of $X$, then $\bigcap_{i=1}^n E_i$ is open. If $F_1,\dots,F_n$ are closed subsets of $X$, then $\bigcup_{i=1}^n F_i$ is closed.
\item[(g)] If $\{E_\alpha\}_{\alpha\in I}$ is a collection of open subsets of $X$, then $\bigcup_{\alpha\in I} E_\alpha$ is open. If $\{F_\alpha\}_{\alpha\in I}$ is a collection of closed subsets of $X$, then $\bigcap_{\alpha\in I} F_\alpha$ is closed.
\item[(h)] For any $E\subseteq X$, $\operatorname{int}(E)$ is the largest open set contained in $E$, i.e. $\operatorname{int}(E)$ is open and for every open set $V\subseteq E$ one has $V\subseteq \operatorname{int}(E)$. Also $\overline{E}$ is the smallest closed set containing $E$, i.e. $\overline{E}$ is closed and for every closed set $K\supseteq E$ one has $\overline{E}\subseteq K$.
\end{enumerate}
\end{proposition}

