\begin{definition}
\label{def:1.15}
[Relative topology]
Let $(X,d)$ be a metric space and let $Y\subseteq X$. The metric subspace of $X$ induced on $Y$ is the metric space $(Y,d|_{Y\times Y})$.

A subset $E\subseteq Y$ is called \emph{relatively open in $Y$} if $E$ is open in the metric space $(Y,d|_{Y\times Y})$, i.e., for every $y\in E$ there exists $r>0$ such that
\[
\label{eq:1.u67}
\{z\in Y: d(y,z)<r\}\subseteq E.
\]
A subset $E\subseteq Y$ is called \emph{relatively closed in $Y$} if $E$ is closed in $(Y,d|_{Y\times Y})$, equivalently if $Y\setminus E$ is relatively open in $Y$.
\end{definition}

\begin{proposition}
\label{prop:1.18}
Let $(X,d)$ be a metric space, let $Y\subseteq X$, and let $E\subseteq Y$.
\begin{enumerate}[(a)]
\item $E$ is open in the subspace metric space $(Y,d|_{Y\times Y})$ if and only if there exists an open set $V\subseteq X$ such that $E=V\cap Y$.
\item $E$ is closed in the subspace metric space $(Y,d|_{Y\times Y})$ if and only if there exists a closed set $K\subseteq X$ such that $E=K\cap Y$.
\end{enumerate}
\end{proposition}

\begin{definition}
\label{def:1.16}
(Subsequences) Let $(X,d)$ be a metric space, let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$ indexed by integers $n\ge m$, and let $(n_j)_{j=1}^{\infty}$ be a strictly increasing sequence of integers such that $n_j\ge m$ for all $j$ (equivalently, $m\le n_1<n_2<n_3<\cdots$). The sequence $(x^{(n_j)})_{j=1}^{\infty}$ is called a \emph{subsequence} of $(x^{(n)})_{n=m}^{\infty}$.
\end{definition}

\begin{lemma}
\label{lem:1.2}
Let $(X,d)$ be a metric space, let $(x^{(n)})_{n=1}^{\infty}$ be a sequence in $X$, and let $x_0\in X$. If $x^{(n)}\to x_0$ as $n\to\infty$, then for every strictly increasing sequence of indices $(n_j)_{j=1}^{\infty}$, the subsequence $(x^{(n_j)})_{j=1}^{\infty}$ converges to $x_0$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:1.2}
Assume $x^{(n)}\to x_0$. Let $(n_j)_{j=1}^{\infty}$ be strictly increasing. To show $x^{(n_j)}\to x_0$, let $\varepsilon>0$ be given. By the definition of convergence, there exists $N\in\mathbb{N}$ such that $d(x^{(n)},x_0)<\varepsilon$ for all $n\ge N$. Since $(n_j)$ is strictly increasing, there exists $J\in\mathbb{N}$ such that $n_J\ge N$; then for all $j\ge J$ one has $n_j\ge n_J\ge N$, hence $d(x^{(n_j)},x_0)<\varepsilon$. Therefore $x^{(n_j)}\to x_0$.
\end{proof}

