\begin{definition}
\label{def:1.17}
[Limit point of a sequence]
Let $(X,d)$ be a metric space, let $m\in\mathbb{Z}$, and let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$. A point $L\in X$ is called a \emph{limit point} of $(x^{(n)})_{n=m}^{\infty}$ if for every $N\ge m$ and every $\epsilon>0$ there exists an integer $n\ge N$ such that $d\bigl(x^{(n)},L\bigr)\le \epsilon$.
\end{definition}

\begin{proposition}
\label{prop:1.19}
Let $(X,d)$ be a metric space, let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$ (with $m\in\mathbb{N}$), and let $L\in X$. The following statements are equivalent:
\begin{enumerate}
\item For every $\varepsilon>0$ and every $N\ge m$, there exists an integer $n\ge N$ such that $d(x^{(n)},L)<\varepsilon$.
\item There exists a strictly increasing sequence of integers $(n_j)_{j=1}^{\infty}$ with $n_1\ge m$ such that $d(x^{(n_j)},L)\to 0$ as $j\to\infty$.
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.19}
(1)$\Rightarrow$(2). For each $j\in\mathbb{N}$, apply (1) with $\varepsilon=1/j$ and $N=m$ to obtain some $n\ge m$ with $d(x^{(n)},L)<1/j$. Construct $(n_j)$ inductively as follows. Choose $n_1\ge m$ such that $d(x^{(n_1)},L)<1$. Given $n_j$, apply (1) with $\varepsilon=1/(j+1)$ and $N=n_j+1$ to obtain $n_{j+1}\ge n_j+1$ such that $d(x^{(n_{j+1})},L)<1/(j+1)$. Then $(n_j)$ is strictly increasing, $n_1\ge m$, and for every $j$,
\[
\label{eq:1.u73}
d(x^{(n_j)},L)<\frac{1}{j},
\]
which implies $d(x^{(n_j)},L)\to 0$, i.e. $x^{(n_j)}\to L$.

(2)$\Rightarrow$(1). Assume there exists a subsequence $(x^{(n_j)})$ with $x^{(n_j)}\to L$. Let $\varepsilon>0$ and $N\ge m$ be given. Choose $J\in\mathbb{N}$ such that for all $j\ge J$ one has $d(x^{(n_j)},L)<\varepsilon$. Since $(n_j)$ is strictly increasing and unbounded, there exists $j\ge J$ with $n_j\ge N$. For this $n=n_j$,
\[
\label{eq:1.u74}
d(x^{(n)},L)=d(x^{(n_j)},L)<\varepsilon,
\]
which is exactly (1).
\end{proof}

