\begin{definition}
\label{def:1.18}
[Cauchy sequence]
Let $(X,d)$ be a metric space, let $m\in\mathbb{N}$, and let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$. The sequence $(x^{(n)})_{n=m}^{\infty}$ is called a \emph{Cauchy sequence} if for every $\epsilon>0$ there exists an integer $N\ge m$ such that
\[
\label{eq:1.u75}
d\bigl(x^{(j)},x^{(k)}\bigr)<\epsilon\quad\text{for all } j,k\ge N.
\]
\end{definition}

\begin{lemma}
\label{lem:1.3}
[Convergent sequences are Cauchy]
Let $(X,d)$ be a metric space and let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$ such that $x^{(n)}\to x_0\in X$ as $n\to\infty$. Then $(x^{(n)})_{n=m}^{\infty}$ is a Cauchy sequence, i.e., for every $\varepsilon>0$ there exists $N\ge m$ such that for all $n,n'\ge N$ one has $d\bigl(x^{(n)},x^{(n')}\bigr)<\varepsilon$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:1.3}
Fix $\varepsilon>0$. Since $x^{(n)}\to x_0$, there exists $N\ge m$ such that for all $n\ge N$,
\[
\label{eq:1.u76}
d\bigl(x^{(n)},x_0\bigr)<\frac{\varepsilon}{2}.
\]
Then for any $n,n'\ge N$, the triangle inequality yields
\[
\label{eq:1.u77}
d\bigl(x^{(n)},x^{(n')}\bigr)\le d\bigl(x^{(n)},x_0\bigr)+d\bigl(x_0,x^{(n')}\bigr)<\frac{\varepsilon}{2}+\frac{\varepsilon}{2}=\varepsilon.
\]
Thus $(x^{(n)})_{n=m}^{\infty}$ is Cauchy.
\end{proof}

