\begin{lemma}
\label{lem:1.4}
Let $(X,d)$ be a metric space and let $(x^{(n)})_{n=m}^{\infty}$ be a Cauchy sequence in $X$. Suppose there exists a subsequence $(x^{(n_j)})_{j=1}^{\infty}$ and a point $x_0\in X$ such that $x^{(n_j)}\to x_0$ as $j\to\infty$. Then $x^{(n)}\to x_0$ as $n\to\infty$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:1.4}
Let $\varepsilon>0$. Since $(x^{(n)})_{n=m}^{\infty}$ is Cauchy, there exists $N\ge m$ such that for all $n,k\ge N$,
\[
\label{eq:1.u78}
d\bigl(x^{(n)},x^{(k)}\bigr)<\varepsilon/2.
\]
Since $x^{(n_j)}\to x_0$, there exists $J$ such that for all $j\ge J$,
\[
\label{eq:1.u79}
d\bigl(x^{(n_j)},x_0\bigr)<\varepsilon/2.
\]
Choose $j\ge J$ with $n_j\ge N$ (possible because $n_j\to\infty$). Then for any $n\ge N$,
\[
\label{eq:1.u80}
d\bigl(x^{(n)},x_0\bigr)\le d\bigl(x^{(n)},x^{(n_j)}\bigr)+d\bigl(x^{(n_j)},x_0\bigr)<\varepsilon/2+\varepsilon/2=\varepsilon.
\]
Thus for all $n\ge N$, $d(x^{(n)},x_0)<\varepsilon$, which proves $x^{(n)}\to x_0$.
\end{proof}

