\begin{definition}
\label{def:1.19}
(Complete metric space) A metric space $(X,d)$ is \emph{complete} if every Cauchy sequence $(x_n)_{n\in\mathbb{N}}$ in $(X,d)$ converges to a point of $X$, i.e., if for every Cauchy sequence there exists $x\in X$ such that $d(x_n,x)\to 0$ as $n\to\infty$.
\end{definition}

\begin{proposition}
\label{prop:1.20}
Let $(X,d)$ be a metric space and let $Y\subseteq X$ be equipped with the subspace metric $d|_{Y\times Y}$.
\begin{enumerate}
\item[(a)] If $(Y,d|_{Y\times Y})$ is complete, then $Y$ is closed in $X$.
\item[(b)] If $(X,d)$ is complete and $Y$ is closed in $X$, then $(Y,d|_{Y\times Y})$ is complete.
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.20}
(a) To show that $Y$ is closed in $X$, it suffices to show that $X\setminus Y$ is open. Let $x\in X\setminus Y$. If $\inf\{d(x,y):y\in Y\}=0$, then there exists a sequence $(y_n)$ in $Y$ such that $d(x,y_n)<1/n$ for all $n$. Then $(y_n)$ is a Cauchy sequence in $X$ since for $m,n$ large,
\[
\label{eq:1.u81}
d(y_m,y_n)\le d(y_m,x)+d(x,y_n)<\frac1m+\frac1n.
\]
Viewed as a sequence in the metric space $(Y,d|_{Y\times Y})$, it is Cauchy, hence converges to some $y\in Y$ by completeness of $Y$. Convergence in the subspace metric means $d(y_n,y)\to 0$ in $X$. By the triangle inequality,
\[
\label{eq:1.u82}
d(x,y)\le d(x,y_n)+d(y_n,y)\to 0,
\]
so $d(x,y)=0$ and therefore $x=y\in Y$, contradicting $x\notin Y$. Hence $\delta:=\inf\{d(x,y):y\in Y\}>0$. Then for any $z\in B(x,\delta/2)$ and any $y\in Y$, the triangle inequality gives
\[
\label{eq:1.u83}
d(z,y)\ge d(x,y)-d(x,z)>\delta-\frac\delta2=\frac\delta2>0,
\]
so $z\notin Y$. Thus $B(x,\delta/2)\subseteq X\setminus Y$, showing $X\setminus Y$ is open and $Y$ is closed.

(b) Let $(y_n)$ be a Cauchy sequence in $(Y,d|_{Y\times Y})$. Then $(y_n)$ is also Cauchy in $(X,d)$, so by completeness of $X$ there exists $x\in X$ such that $y_n\to x$ in $X$. Since $Y$ is closed in $X$ and $(y_n)\subseteq Y$, the limit $x$ belongs to $Y$. Therefore $y_n\to x$ in the subspace metric on $Y$, so $(Y,d|_{Y\times Y})$ is complete.
\end{proof}

