\begin{proposition}
\label{prop:1.21}
Let $(X,d)$ be a metric space, let $m\in\mathbb{N}$, and let $\bigl(x^{(n)}\bigr)_{n=m}^{\infty}$ be a sequence in $X$. Let $L\in X$. Assume that $L$ is a limit point of the sequence, i.e., for every $\varepsilon>0$ and every $N\ge m$ there exists $n\ge N$ such that $d\bigl(x^{(n)},L\bigr)<\varepsilon$. Then $L$ is an adherent point of the set $A:=\{x^{(n)}: n\ge m\}$, i.e., for every $\varepsilon>0$ there exists $a\in A$ such that $d(a,L)<\varepsilon$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.21}
Let $\varepsilon>0$ be given. By the hypothesis that $L$ is a limit point of the sequence, with $N:=m$ there exists an index $n\ge m$ such that $d\bigl(x^{(n)},L\bigr)<\varepsilon$. Set $a:=x^{(n)}$. Then $a\in A$ and $d(a,L)<\varepsilon$. Since $\varepsilon>0$ was arbitrary, $L$ is an adherent point of $A$.
\end{proof}

