\begin{proposition}
\label{prop:1.22}
Let $(X,d)$ be a metric space, and let $(x_n)_{n\in\mathbb{N}}$ be a Cauchy sequence in $X$. If $x_n\to x$ and $x_n\to y$ for some $x,y\in X$, then $x=y$. Equivalently, a Cauchy sequence in a metric space has at most one limit.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.22}
Let $\varepsilon>0$. Since $x_n\to x$, there exists $N_1\in\mathbb{N}$ such that $d(x_n,x)<\varepsilon/2$ for all $n\ge N_1$. Since $x_n\to y$, there exists $N_2\in\mathbb{N}$ such that $d(x_n,y)<\varepsilon/2$ for all $n\ge N_2$. Let $N=\max\{N_1,N_2\}$. Then, for all $n\ge N$, the triangle inequality gives
\[
\label{eq:1.u84}
d(x,y)\le d(x,x_n)+d(x_n,y)<\varepsilon/2+\varepsilon/2=\varepsilon.
\]
Since $\varepsilon>0$ is arbitrary, it follows that $d(x,y)=0$, hence $x=y$.
\end{proof}

