\begin{definition}
\label{def:1.20}
[Completion via formal limits]
Let $(X,d)$ be a metric space.
\begin{enumerate}
\item For every Cauchy sequence $(x_n)_{n=1}^{\infty}$ in $X$, introduce a formal symbol $\mathrm{LIM}_{n\to\infty} x_n$.
\item Define an equivalence relation $\sim$ on such formal symbols by
\[
\label{eq:1.u85}
\mathrm{LIM}_{n\to\infty} x_n \sim \mathrm{LIM}_{n\to\infty} y_n \iff \lim_{n\to\infty} d(x_n,y_n)=0.
\]
\item Define $\overline X$ to be the set of equivalence classes of these formal symbols modulo $\sim$.
\item Define $d_{\overline X}:\overline X\times \overline X\to[0,\infty)$ by
\[
\label{eq:1.u86}
d_{\overline X}\bigl(\mathrm{LIM}_{n\to\infty} x_n,\mathrm{LIM}_{n\to\infty} y_n\bigr):=\lim_{n\to\infty} d(x_n,y_n),
\]
where representatives are chosen from the corresponding equivalence classes.
\end{enumerate}
\end{definition}

\begin{proposition}
\label{prop:1.23}
Let $(X,d)$ be a metric space, and let $\mathcal{C}$ denote the set of all Cauchy sequences in $X$. For Cauchy sequences $(x_n)$ and $(y_n)$ in $X$, define a relation $\sim$ on the set of formal limits $\{\mathrm{LIM}_{n\to\infty} x_n : (x_n)\in\mathcal{C}\}$ by
\[
\label{eq:1.u87}
\mathrm{LIM}_{n\to\infty} x_n \sim \mathrm{LIM}_{n\to\infty} y_n \iff \lim_{n\to\infty} d(x_n,y_n)=0.
\]
Then $\sim$ is an equivalence relation.
\end{proposition}

\begin{proposition}
\label{prop:1.24}
Let $(X,d)$ be a metric space. Define $\overline X$ as the set of equivalence classes of Cauchy sequences in $X$, where two Cauchy sequences $(x_n)$ and $(y_n)$ are equivalent if $d(x_n,y_n)\to 0$ as $n\to\infty$. For equivalence classes $[(x_n)],[(y_n)]\in\overline X$, define
\[
\label{eq:1.u91}
d_{\overline X}([(x_n)],[(y_n)]) := \lim_{n\to\infty} d(x_n,y_n).
\]
Then $d_{\overline X}$ is well-defined (independent of the choice of representatives) and $(\overline X,d_{\overline X})$ is a metric space.
\end{proposition}

\begin{theorem}
\label{thm:1.4}
Let $(X,d)$ be a metric space. Define $\overline X$ to be the set of equivalence classes of Cauchy sequences in $X$ under the relation $(x_n)\sim(y_n)$ if and only if $d(x_n,y_n)\to 0$ as $n\to\infty$. For $[(x_n)],[(y_n)]\in\overline X$ define
\[
\label{eq:1.u97}
d_{\overline X}([(x_n)],[(y_n)]) := \lim_{n\to\infty} d(x_n,y_n),
\]
which is well-defined. Then the metric space $(\overline X,d_{\overline X})$ is complete.
\end{theorem}

\begin{proposition}
\label{prop:1.25}
Let $(X,d)$ be a metric space. Let $\overline X$ be the set of equivalence classes of Cauchy sequences in $X$ under the relation $(x_n)\sim(y_n)$ if $\lim_{n\to\infty} d(x_n,y_n)=0$, and define
\[
\label{eq:1.u111}
d_{\overline X}\big(\mathrm{LIM}\,x_n,\mathrm{LIM}\,y_n\big):=\lim_{n\to\infty} d(x_n,y_n),
\]
where $\mathrm{LIM}\,x_n$ denotes the equivalence class of a Cauchy sequence $(x_n)$. Define $\iota:X\to\overline X$ by $\iota(x)=\mathrm{LIM}\,x_n$, where $x_n\equiv x$ is the constant sequence.
\begin{enumerate}
\item For all $x,y\in X$, one has $x=y$ if and only if $\iota(x)=\iota(y)$.
\item For all $x,y\in X$, one has $d(x,y)=d_{\overline X}(\iota(x),\iota(y))$.
\end{enumerate}
In particular, $\iota$ is an isometric embedding of $(X,d)$ into $(\overline X,d_{\overline X})$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.25}
(1) If $x=y$, then the constant sequences $x_n\equiv x$ and $y_n\equiv y$ agree, hence are equivalent, so $\iota(x)=\iota(y)$. Conversely, if $\iota(x)=\iota(y)$, then the constant sequences $x_n\equiv x$ and $y_n\equiv y$ are equivalent, so
\[
\label{eq:1.u112}
0=\lim_{n\to\infty} d(x_n,y_n)=\lim_{n\to\infty} d(x,y)=d(x,y),
\]
which implies $x=y$.

(2) For $x,y\in X$, using the definition of $d_{\overline X}$ and the constant sequences $x_n\equiv x$, $y_n\equiv y$,
\[
\label{eq:1.u113}
d_{\overline X}(\iota(x),\iota(y))=\lim_{n\to\infty} d(x_n,y_n)=\lim_{n\to\infty} d(x,y)=d(x,y).
\]
Thus $\iota$ preserves distances and is injective by (1), hence is an isometric embedding.
\end{proof}

