\begin{proposition}
\label{prop:1.26}
Let $(X,d)$ be a metric space. Let $(\overline X,d_{\overline X})$ be the completion of $X$ constructed by formal limits, and identify $X$ with its canonical image in $\overline X$. Then $\overline X$ is the closure of $X$ in $\overline X$, i.e. $\overline X=\overline{X}^{\,\overline X}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.26}
Let $\xi\in\overline X$. By the construction of $\overline X$ via formal limits, $\xi$ is an equivalence class of Cauchy sequences $(x_n)$ in $X$. For each $n$, let $\iota(x_n)\in\overline X$ denote the image of $x_n$ under the canonical embedding $\iota:X\to\overline X$.

By definition of the metric $d_{\overline X}$, one has
\[
\label{eq:1.u114}
d_{\overline X}(\iota(x_n),\xi)=\lim_{m\to\infty} d(x_n,x_m).
\]
Since $(x_n)$ is Cauchy in $X$, the right-hand side tends to $0$ as $n\to\infty$. Hence $d_{\overline X}(\iota(x_n),\xi)\to 0$, so $\iota(x_n)\to \xi$ in $\overline X$. Therefore every $\xi\in\overline X$ lies in the closure of $\iota(X)$.

Thus $\overline X\subseteq \overline{\iota(X)}^{\,\overline X}$. The reverse inclusion is immediate because $\overline{\iota(X)}^{\,\overline X}\subseteq \overline X$. Hence $\overline{\iota(X)}^{\,\overline X}=\overline X$, and under the identification of $X$ with its image this is $\overline{X}^{\,\overline X}=\overline X$.
\end{proof}

content:
\begin{proposition}
\label{prop:1.27}
Let $(X,d)$ be a metric space. Let $(\overline X,d_{\overline X})$ be the completion of $X$ constructed via formal limits of Cauchy sequences, and identify $X$ with its canonical image in $\overline X$ (sending $x\in X$ to the equivalence class of the constant sequence $(x,x,\dots)$). Let $(x_n)_{n=1}^\infty$ be a Cauchy sequence in $X$ that converges in $X$ to some $x\in X$ with respect to $d$. Then the limit of $(x_n)$ in the metric space $(\overline X,d_{\overline X})$ equals the embedded point $x\in \overline X$, i.e.
\[
\label{eq:1.u115}
\lim_{n\to\infty} x_n = \mathrm{LIM}_{n\to\infty} x_n.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.27}
Write $\iota\colon X\to \overline X$ for the canonical embedding, so $\iota(x)$ is the equivalence class of the constant sequence $(x,x,\dots)$. By definition of the completion via formal limits, $\mathrm{LIM}_{n\to\infty} x_n$ is the equivalence class of the Cauchy sequence $(x_n)$.

Fix $\varepsilon>0$. Since $x_n\to x$ in $(X,d)$, there exists $N\in\mathbb{N}$ such that $d(x_n,x)<\varepsilon$ for all $n\ge N$. For each $n\ge N$, the distance in $\overline X$ between $\iota(x_n)$ and $\iota(x)$ is
\[
\label{eq:1.u116}
d_{\overline X}(\iota(x_n),\iota(x))=\lim_{m\to\infty} d(x_n,x)=d(x_n,x),
\]
because both representatives are constant sequences. Hence $d_{\overline X}(\iota(x_n),\iota(x))<\varepsilon$ for all $n\ge N$, so $\iota(x_n)\to \iota(x)$ in $(\overline X,d_{\overline X})$.

It remains to identify $\iota(x)$ with the formal limit class of $(x_n)$. Let $[x_n]$ denote the equivalence class of the sequence $(x_n)$ in $\overline X$. By definition of the metric on $\overline X$,
\[
\label{eq:1.u117}
d_{\overline X}([x_n],\iota(x))=\lim_{n\to\infty} d(x_n,x)=0,
\]
so $[x_n]=\iota(x)$ in $\overline X$. Therefore $\lim_{n\to\infty} x_n=\iota(x)=\mathrm{LIM}_{n\to\infty} x_n$ in $\overline X$.
\end{proof}

