\begin{definition}
\label{def:1.21}
A subset $X\subseteq \mathbb{R}$ is \emph{sequentially compact} if every sequence $(x_n)$ in $X$ has a convergent subsequence $(x_{n_k})$ whose limit belongs to $X$.
\end{definition}

\begin{theorem}
\label{thm:1.5}
[Heine--Borel theorem on $\mathbb{R}$]
Let $X\subseteq\mathbb{R}$. The following statements are equivalent.
\begin{enumerate}
\item $X$ is closed and bounded.
\item Every sequence $(x_n)_{n\in\mathbb{N}}$ in $X$ has a subsequence $(x_{n_k})_{k\in\mathbb{N}}$ that converges to a limit $x\in X$.
\end{enumerate}
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:1.5}
\emph{(1 $\Rightarrow$ 2).} Assume that $X$ is closed and bounded. Let $(x_n)$ be a sequence in $X$. Since $X$ is bounded, there exists $M>0$ such that $|x_n|\le M$ for all $n$, hence $(x_n)$ is a bounded sequence in $\mathbb{R}$. By the Bolzano--Weierstrass theorem, $(x_n)$ has a convergent subsequence $(x_{n_k})$ with limit $x\in\mathbb{R}$. Since all terms of $(x_{n_k})$ lie in $X$ and $X$ is closed, the limit satisfies $x\in X$. Thus (2) holds.

\emph{(2 $\Rightarrow$ 1).} Assume that every sequence in $X$ has a subsequence converging to a point of $X$.

First, $X$ is bounded. If $X$ were unbounded, then for each $n\in\mathbb{N}$ one could choose $x_n\in X$ with $|x_n|>n$. Then $(x_n)$ has no convergent subsequence because any convergent subsequence in $\mathbb{R}$ must be bounded, whereas $|x_n|>n$ forces every subsequence to be unbounded. This contradicts (2). Hence $X$ is bounded.

Second, $X$ is closed. Let $(y_n)$ be a sequence in $X$ converging in $\mathbb{R}$ to some $y$. By (2), the sequence $(y_n)$ has a subsequence $(y_{n_k})$ converging to some $z\in X$. Since $(y_{n_k})$ is a subsequence of a convergent sequence, it also converges to $y$, so $y=z\in X$. Therefore every limit of a convergent sequence in $X$ lies in $X$, and $X$ is closed.

Thus $X$ is closed and bounded.
\end{proof}

content:
\begin{definition}
\label{def:1.22}
[Compactness]
Let $(X,d)$ be a metric space. The space $(X,d)$ is called \emph{compact} if for every sequence $(x_n)_{n\in\mathbb{N}}$ in $X$ there exist a strictly increasing function $k:\mathbb{N}\to\mathbb{N}$ and a point $x\in X$ such that $d(x_{k(n)},x)\to 0$ as $n\to\infty$.

Let $Y\subseteq X$. The subset $Y$ is called \emph{compact} (in $X$) if the metric space $(Y,d_Y)$ is compact, where $d_Y:Y\times Y\to\mathbb{R}$ is the restriction $d_Y=d\vert_{Y\times Y}$.
\end{definition}

\begin{definition}
\label{def:1.23}
[Bounded sets]
Let $(X,d)$ be a metric space and let $Y\subseteq X$. The set $Y$ is called \emph{bounded} if there exist a point $x\in X$ and a real number $r\in\mathbb{R}$ with $0\le r<\infty$ such that $Y\subseteq B(x,r)=\{y\in X: d(x,y)<r\}$. The metric space $(X,d)$ is called \emph{bounded} if the set $X$ is bounded.
\end{definition}

\begin{proposition}
\label{prop:1.28}
Let $(X,d)$ be a compact metric space. Then $(X,d)$ is complete and bounded.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.28}
First, $(X,d)$ is bounded. Fix $x_0\in X$. The family of open balls $\{B(x_0,n): n\in\mathbb{N}\}$ is an open cover of $X$, since for every $x\in X$ there exists $n\in\mathbb{N}$ with $d(x,x_0)<n$. By compactness, there exists $N\in\mathbb{N}$ such that $X\subseteq B(x_0,N)$. Hence $d(x,x_0)\le N$ for all $x\in X$, so $\operatorname{diam}(X)\le 2N$ and $X$ is bounded.

Next, $(X,d)$ is complete. Let $(x_n)$ be a Cauchy sequence in $X$. By compactness, every sequence in $X$ has a convergent subsequence, so there exist $(x_{n_k})$ and $x\in X$ with $x_{n_k}\to x$. It remains to show $x_n\to x$. Given $\varepsilon>0$, choose $K$ such that $d(x_m,x_n)<\varepsilon/2$ for all $m,n\ge K$ (Cauchy property). Choose $k$ with $n_k\ge K$ and $d(x_{n_k},x)<\varepsilon/2$ (since $x_{n_k}\to x$). Then for every $n\ge K$,
\[
\label{eq:1.u118}
d(x_n,x)\le d(x_n,x_{n_k})+d(x_{n_k},x)<\varepsilon/2+\varepsilon/2=\varepsilon.
\]
Thus $x_n\to x$, so every Cauchy sequence converges in $X$, and $(X,d)$ is complete.
\end{proof}

