\begin{theorem}
\label{thm:1.6}
(Compact subsets of metric spaces are closed and bounded)
Let $(X,d)$ be a metric space and let $Y\subseteq X$ be compact. Then:
\begin{enumerate}
\item $Y$ is closed in $X$.
\item $Y$ is bounded, i.e. there exist $x_0\in X$ and $R>0$ such that $Y\subseteq \{x\in X: d(x,x_0)\le R\}$.
\end{enumerate}
\end{theorem}

\begin{theorem}
\label{thm:1.7}
[Heine--Borel theorem]
Let $n\in\mathbb{N}$, and let $d$ be one of the following metrics on $\mathbb{R}^n$: the Euclidean metric, the taxicab metric, or the sup norm metric. For a set $E\subseteq\mathbb{R}^n$, the following are equivalent:
\begin{enumerate}
\item $E$ is compact (i.e., every open cover of $E$ admits a finite subcover).
\item $E$ is closed and bounded.
\end{enumerate}
\end{theorem}

\begin{definition}
\label{def:1.24}
Let $(X,d)$ be a metric space. A subset $K\subseteq X$ is \emph{compact} if every open cover of $K$ has a finite subcover; that is, for every family of open sets $(U_i)_{i\in I}$ in $X$ such that $K\subseteq\bigcup_{i\in I} U_i$, there exist indices $i_1,\dots,i_n\in I$ with $K\subseteq U_{i_1}\cup\cdots\cup U_{i_n}$.
\end{definition}

\begin{proposition}
\label{prop:1.29}
Let $(X,d)$ be a metric space and equip $\mathbb{Z}$ with the discrete metric $d(m,n)=\mathbf{1}_{m\neq n}$. Then $\mathbb{Z}$ is complete and bounded, but not compact.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.29}
Completeness holds because every Cauchy sequence in the discrete metric is eventually constant, hence convergent in $\mathbb{Z}$. Boundedness holds since $d(m,n)\le 1$ for all $m,n\in\mathbb{Z}$. The sequence $(n)_{n\ge 1}$ in $\mathbb{Z}$ has no convergent subsequence, because convergence in the discrete metric implies eventual constancy. Hence $\mathbb{Z}$ is not sequentially compact, and therefore not compact.
\end{proof}

content:
\begin{theorem}
\label{thm:1.8}
Let $(X,d)$ be a metric space, let $Y\subseteq X$ be compact, and let $(V_{\alpha})_{\alpha\in A}$ be a family of open subsets of $X$ such that
\[
\label{eq:1.u125}
Y\subseteq \bigcup_{\alpha\in A} V_{\alpha}.
\]
Then there exists a finite subset $F\subseteq A$ such that
\[
\label{eq:1.u126}
Y\subseteq \bigcup_{\alpha\in F} V_{\alpha}.
\]
\end{theorem}

\begin{definition}
\label{def:1.25}
[Compactness via open covers]\label{def:compact-open-cover}
A topological space $Y$ is \emph{compact} if every open cover of $Y$ has a finite subcover.
\end{definition}

\begin{theorem}
\label{thm:1.9}
[Heine--Borel property implies compactness]
Let $Y$ be a topological space. If every open cover of $Y$ admits a finite subcover, then $Y$ is compact.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:1.9}
Assume that every open cover of $Y$ has a finite subcover. To prove that $Y$ is compact, it suffices to verify the defining condition for compactness: for every collection $\mathcal U$ of open subsets of $Y$ such that $Y=\bigcup_{U\in\mathcal U}U$, there exists a finite subcollection $\mathcal U_0\subseteq \mathcal U$ with $Y=\bigcup_{U\in\mathcal U_0}U$. This holds by the assumption applied to the open cover $\mathcal U$. Hence $Y$ is compact.
\end{proof}

