\begin{theorem}
\label{thm:1.10}
Let $(K_n)_{n\in\mathbb{N}}$ be a sequence of non-empty compact subsets of a metric space $(X,d)$ such that $K_{n+1}\subseteq K_n$ for all $n\in\mathbb{N}$. Then
\[
\label{eq:1.u133}
\bigcap_{n\in\mathbb{N}} K_n\neq\varnothing.
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:1.10}
Assume for contradiction that $\bigcap_{n\in\mathbb{N}} K_n=\varnothing$. Then the family of open sets
\[
\label{eq:1.u134}
\mathcal{U}:=\{X\setminus K_n: n\in\mathbb{N}\}
\]
covers $K_1$, since for every $x\in K_1$ there exists $n$ with $x\notin K_n$, hence $x\in X\setminus K_n$. Because $K_1$ is compact, there exists a finite subcover $X\setminus K_{n_1},\dots,X\setminus K_{n_m}$ of $K_1$. Let $N:=\max\{n_1,\dots,n_m\}$. Since the sequence is nested, $K_N\subseteq K_{n_i}$ for each $i$, hence $X\setminus K_{n_i}\subseteq X\setminus K_N$. Therefore $X\setminus K_N$ alone covers $K_1$, so $K_1\subseteq X\setminus K_N$, equivalently $K_1\cap K_N=\varnothing$. This contradicts $K_N\subseteq K_1$ and the non-emptiness of $K_N$. Hence $\bigcap_{n\in\mathbb{N}} K_n\neq\varnothing$.
\end{proof}

content:
\begin{theorem}
\label{thm:1.11}
Let $(X,d)$ be a metric space, and let $(K_n)_{n\in\mathbb{N}}$ be a sequence of nonempty compact subsets of $X$ such that $K_{n+1}\subseteq K_n$ for all $n\in\mathbb{N}$. Then
\[
\label{eq:1.u135}
\bigcap_{n=1}^\infty K_n \neq \varnothing.
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:1.11}
For each $n\in\mathbb{N}$ choose a point $x_n\in K_n$. Since $K_1$ is compact and $(x_n)$ is a sequence in $K_1$, there exists a subsequence $(x_{n_k})_{k\in\mathbb{N}}$ converging to some $x\in K_1$.

Fix $m\in\mathbb{N}$. For all $k$ large enough one has $n_k\ge m$, and then, by the nesting property, $K_{n_k}\subseteq K_m$. Hence $x_{n_k}\in K_m$ for all sufficiently large $k$. Because $K_m$ is compact, it is closed, so it contains the limit of any convergent sequence of its points; therefore $x\in K_m$.

Since $m$ was arbitrary, $x\in\bigcap_{m=1}^\infty K_m$, proving that the intersection is nonempty.
\end{proof}

