\begin{theorem}
\label{thm:1.12}
Let $(X,d)$ be a metric space.
\begin{enumerate}[(a)]
\item If $Y\subseteq X$ is compact and $Z\subseteq Y$, then $Z$ is compact if and only if $Z$ is closed in $Y$.
\item If $Y_1,\ldots,Y_n\subseteq X$ are compact, then $\bigcup_{i=1}^n Y_i$ is compact.
\item Every finite subset of $X$ (including $\varnothing$) is compact.
\end{enumerate}
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:1.12}
Compactness is understood in the open-cover sense.

\begin{enumerate}[(a)]
\item Suppose first that $Z$ is compact. To show that $Z$ is closed in $Y$, it suffices to show that $Y\setminus Z$ is open in $Y$. Let $y\in Y\setminus Z$. For each $z\in Z$, since $y\neq z$ there exists $r_z>0$ such that the open balls $B(y,r_z)$ and $B(z,r_z)$ are disjoint. Then $\{B(z,r_z): z\in Z\}$ is an open cover of $Z$, so by compactness there exist $z_1,\ldots,z_m\in Z$ such that $Z\subseteq \bigcup_{j=1}^m B(z_j,r_{z_j})$. Let $r:=\min_{1\le j\le m} r_{z_j}>0$. Then $B(y,r)\cap Z=\varnothing$, hence $B(y,r)\cap Y\subseteq Y\setminus Z$. This shows $Y\setminus Z$ is open in $Y$, so $Z$ is closed in $Y$.

Conversely, assume $Z$ is closed in $Y$ and that $Y$ is compact. Let $\{U_\alpha\}_{\alpha\in A}$ be an open cover of $Z$ by sets open in $X$. Then $\{U_\alpha\}_{\alpha\in A}\cup\{X\setminus Z\}$ is an open cover of $Y$ (since $Y\subseteq Z\cup (X\setminus Z)$). By compactness of $Y$, there exist $\alpha_1,\ldots,\alpha_k\in A$ such that
\[
\label{eq:1.u136}
Y\subseteq \bigcup_{i=1}^k U_{\alpha_i}\cup (X\setminus Z).
\]
Intersecting with $Z$ yields $Z\subseteq \bigcup_{i=1}^k U_{\alpha_i}$, so $Z$ is compact.

\item Let $Y:=\bigcup_{i=1}^n Y_i$ and let $\{U_\alpha\}_{\alpha\in A}$ be an open cover of $Y$. For each $i$, the family $\{U_\alpha\}_{\alpha\in A}$ covers $Y_i$, so by compactness of $Y_i$ there exist finitely many indices $\alpha_{i,1},\ldots,\alpha_{i,k_i}$ such that $Y_i\subseteq \bigcup_{j=1}^{k_i} U_{\alpha_{i,j}}$. Then the finite subfamily consisting of all $U_{\alpha_{i,j}}$ (for $1\le i\le n$, $1\le j\le k_i$) covers $\bigcup_{i=1}^n Y_i=Y$. Hence $Y$ is compact.

\item If $F=\varnothing$, then every open cover of $F$ has the empty subcover, so $F$ is compact. If $F=\{x_1,\ldots,x_m\}$ is nonempty and $\{U_\alpha\}_{\alpha\in A}$ is an open cover of $F$, then for each $j$ choose $\alpha(j)\in A$ such that $x_j\in U_{\alpha(j)}$. The finite subfamily $\{U_{\alpha(1)},\ldots,U_{\alpha(m)}\}$ covers $F$, so $F$ is compact.
\end{enumerate}
\end{proof}

