\begin{definition}
\label{def:1.26}
A metric space $(X,d)$ is \emph{totally bounded} if for every $\varepsilon>0$ there exist $n\in\mathbb{N}$ and points $x^{(1)},\dots,x^{(n)}\in X$ such that
\[
\label{eq:1.u137}
X=\bigcup_{i=1}^n B(x^{(i)},\varepsilon).
\]
\end{definition}

\begin{proposition}
\label{prop:1.30}
[Comparison of $\ell^1$ and $\ell^2$ metrics]
Let $n\ge 1$ and let $x,y\in\mathbb{R}^n$. Then
\[
\label{eq:1.u138}
d_{\ell^2}(x,y)\le d_{\ell^1}(x,y)\le \sqrt{n}\, d_{\ell^2}(x,y).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.30}
Let $x=(x_1,\dots,x_n)$ and $y=(y_1,\dots,y_n)$. Set $a_i=|x_i-y_i|\ge 0$ for $i=1,\dots,n$.

For the first inequality, note that for each $i$, $a_i^2\le a_i\sum_{j=1}^n a_j$. Summing over $i$ gives $\sum_{i=1}^n a_i^2\le \left(\sum_{i=1}^n a_i\right)^2$. Taking square roots yields $d_{\ell^2}(x,y)\le d_{\ell^1}(x,y)$.

For the second inequality, since $a_i\le \max_j a_j$ for each $i$, we have $\sum_{i=1}^n a_i\le n\max_j a_j$. Also, $\sum_{i=1}^n a_i^2\ge (\max_j a_j)^2$, so $\max_j a_j\le \sqrt{\sum_{i=1}^n a_i^2}$. Therefore $d_{\ell^1}(x,y)=\sum_{i=1}^n a_i\le n\max_j a_j\le n\cdot d_{\ell^2}(x,y)/\sqrt{n}=\sqrt{n}\,d_{\ell^2}(x,y)$.
\end{proof}

content:
\begin{proposition}
\label{prop:1.31}
[Comparison of $\ell^2$ and $\ell^\infty$ metrics]
Let $n\ge 1$ and let $x,y\in\mathbb{R}^n$. Then
\[
\label{eq:1.u139}
\frac{1}{\sqrt{n}}\,d_{\ell^2}(x,y)\le d_{\ell^\infty}(x,y)\le d_{\ell^2}(x,y).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.31}
Let $x=(x_1,\dots,x_n)$ and $y=(y_1,\dots,y_n)$. Set $a_i=|x_i-y_i|\ge 0$.

For the upper bound: $d_{\ell^\infty}(x,y)=\max_i a_i\le \sqrt{\sum_{i=1}^n a_i^2}=d_{\ell^2}(x,y)$, since $(\max_i a_i)^2\le \sum_{i=1}^n a_i^2$.

For the lower bound: $d_{\ell^2}(x,y)^2=\sum_{i=1}^n a_i^2\le n(\max_i a_i)^2=n\cdot d_{\ell^\infty}(x,y)^2$. Taking square roots gives $d_{\ell^2}(x,y)\le \sqrt{n}\,d_{\ell^\infty}(x,y)$, which rearranges to $(1/\sqrt{n})d_{\ell^2}(x,y)\le d_{\ell^\infty}(x,y)$.
\end{proof}

content:
\begin{proposition}
\label{prop:1.32}
[Equivalence of $\ell^1$, $\ell^2$, $\ell^\infty$ metrics]
Let $n\ge 1$. The metrics $d_{\ell^1}$, $d_{\ell^2}$, and $d_{\ell^\infty}$ on $\mathbb{R}^n$ are equivalent in the following sense: a sequence $(x^{(k)})_{k=1}^\infty$ in $\mathbb{R}^n$ converges to $x\in\mathbb{R}^n$ with respect to one of these metrics if and only if it converges to $x$ with respect to each of the other two metrics.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.32}
By Proposition 1.30, $d_{\ell^2}\le d_{\ell^1}\le \sqrt{n}\,d_{\ell^2}$. By Proposition 1.31, $(1/\sqrt{n})d_{\ell^2}\le d_{\ell^\infty}\le d_{\ell^2}$.

If $x^{(k)}\to x$ in $d_{\ell^2}$, then $d_{\ell^2}(x^{(k)},x)\to 0$. By the inequalities, $d_{\ell^1}(x^{(k)},x)\le \sqrt{n}\,d_{\ell^2}(x^{(k)},x)\to 0$ and $d_{\ell^\infty}(x^{(k)},x)\le d_{\ell^2}(x^{(k)},x)\to 0$.

Conversely, if $x^{(k)}\to x$ in $d_{\ell^1}$, then $d_{\ell^2}(x^{(k)},x)\le d_{\ell^1}(x^{(k)},x)\to 0$. If $x^{(k)}\to x$ in $d_{\ell^\infty}$, then $d_{\ell^2}(x^{(k)},x)\le \sqrt{n}\,d_{\ell^\infty}(x^{(k)},x)\to 0$.
\end{proof}

