\begin{lemma}
\label{lem:1.5}
[Subsequence of Cauchy sequence is Cauchy]
Let $(X,d)$ be a metric space and let $(x^{(n)})_{n=m}^\infty$ be a Cauchy sequence in $X$. Then every subsequence $(x^{(n_j)})_{j=1}^\infty$ of $(x^{(n)})_{n=m}^\infty$ is also a Cauchy sequence.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:1.5}
Let $\varepsilon>0$. Since $(x^{(n)})_{n=m}^\infty$ is Cauchy, there exists $N\ge m$ such that for all $j,k\ge N$, $d(x^{(j)},x^{(k)})<\varepsilon$.

Let $(x^{(n_j)})_{j=1}^\infty$ be a subsequence. Since $(n_j)$ is strictly increasing with $n_j\ge m$ for all $j$, there exists $J\in\mathbb{N}$ such that $n_j\ge N$ for all $j\ge J$.

For any $j,k\ge J$, we have $n_j,n_k\ge N$, so $d(x^{(n_j)},x^{(n_k)})<\varepsilon$. This shows $(x^{(n_j)})_{j=1}^\infty$ is Cauchy.
\end{proof}

content:
\begin{proposition}
\label{prop:1.33}
[Complete subspaces are closed]
Let $(X,d)$ be a metric space and let $Y\subseteq X$ be a subspace. If the metric subspace $(Y,d|_{Y\times Y})$ is complete, then $Y$ is closed in $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:1.33}
We show that $Y$ contains all its adherent points. Let $x\in X$ be an adherent point of $Y$. Then there exists a sequence $(y_n)_{n=1}^\infty$ in $Y$ such that $y_n\to x$ in $X$.

Since $(y_n)$ converges, it is a Cauchy sequence in $X$. Since each $y_n\in Y$, $(y_n)$ is a Cauchy sequence in $(Y,d|_{Y\times Y})$.

By completeness of $Y$, $(y_n)$ converges to some $y\in Y$. By uniqueness of limits in metric spaces, $x=y\in Y$.

Thus $Y$ contains all its adherent points, so $Y$ is closed.
\end{proof}

